input.command:
mkdir -p /tmp/d && cd /tmp/d && curl -s -o o.csv https://raw.githubusercontent.com/rfordatascience/tidytuesday/6753376ef104727ef0ca3e3db6f2ca580c0d5a7b/data/2026/2026-03-31/ocean_temperature.csv; head -3 o.csv; wc -l o.csv; python3 -I -c "
import csv,collections
d=collections.defaultdict(list)
for r in csv.DictReader(open('o.csv')):
  if r['mean_temperature_degree_c'] not in ('','NA'): d[(r['sensor_depth_at_low_tide_m'],r['date'][:7])].append(float(r['mean_temperature_degree_c']))
for dep in ['2','10','40']:
  print(dep,[ (m,round(sum(v)/len(v),1)) for (k,m),v in sorted(d.items()) if k==dep and m[5:] in('02','08')])
"

cat > spec.vl.json <<'EOF'
{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "title": {
    "text": "Monthly mean water temperature by sensor depth, Birchy Head, Nova Scotia (2018–2025)",
    "subtitle": "Every summer the top 2–5 m warm far more than deeper water, which stays cold (mostly below about 8 °C at 30–40 m) year-round; in winter all depths cool to a similar 1–4 °C. Blank cells: no data that month.",
    "anchor": "start", "fontSize": 18, "subtitleFontSize": 13, "subtitlePadding": 6
  },
  "width": 1180,
  "height": 560,
  "data": {
    "url": "https://raw.githubusercontent.com/rfordatascience/tidytuesday/6753376ef104727ef0ca3e3db6f2ca580c0d5a7b/data/2026/2026-03-31/ocean_temperature.csv",
    "format": {"type": "csv", "parse": {"date": "date:'%Y-%m-%d'", "sensor_depth_at_low_tide_m": "number", "mean_temperature_degree_c": "number"}}
  },
  "transform": [
    {"filter": "isValid(datum.mean_temperature_degree_c) && isFinite(datum.mean_temperature_degree_c)"},
    {"timeUnit": "yearmonth", "field": "date", "as": "month"},
    {"aggregate": [
      {"op": "mean", "field": "mean_temperature_degree_c", "as": "temp"},
      {"op": "count", "as": "days"}
    ], "groupby": ["month", "sensor_depth_at_low_tide_m"]}
  ],
  "mark": {"type": "rect", "stroke": "white", "strokeWidth": 0.5},
  "encoding": {
    "x": {
      "field": "month", "type": "temporal", "timeUnit": "yearmonth", "bandPosition": 0,
      "title": "Month",
      "axis": {"format": "%Y", "tickCount": {"interval": "year", "step": 1}, "labelAlign": "left", "grid": false, "labelFontSize": 12, "titleFontSize": 13}
    },
    "y": {
      "field": "sensor_depth_at_low_tide_m", "type": "ordinal", "sort": "ascending",
      "title": "Sensor depth at low tide (m)",
      "axis": {"labelFontSize": 12, "titleFontSize": 13}
    },
    "color": {
      "field": "temp", "type": "quantitative",
      "title": "Monthly mean temperature (°C)",
      "scale": {"scheme": "redyellowblue", "reverse": true},
      "legend": {"orient": "bottom", "direction": "horizontal", "gradientLength": 400, "titleFontSize": 12, "labelFontSize": 11, "titleLimit": 400}
    },
    "tooltip": [
      {"field": "month", "type": "temporal", "timeUnit": "yearmonth", "title": "Month"},
      {"field": "sensor_depth_at_low_tide_m", "type": "ordinal", "title": "Depth (m)"},
      {"field": "temp", "type": "quantitative", "format": ".2f", "title": "Mean temp (°C)"},
      {"field": "days", "type": "quantitative", "title": "Days with data"}
    ]
  },
  "config": {"view": {"stroke": null}}
}
EOF
render spec.vl.json

